// Guards the two halves of the invariant sidebars.js states in prose for
// `architecturesSidebar`: "only the two repo-authored pages belong in the
// menu. The imported architecture pages (see scripts/lib/architecture-pages.mjs)
// stay out of every sidebar so they keep rendering full-width."
//
// That sidebar is the one hand-listed sidebar in the file. Every other sidebar
// is `{type: 'autogenerated'}`, and the only test that reads sidebar contents
// at all -- 'every autogenerated sidebar points at a docs directory with
// content' in tests/site-config.test.mjs -- opens with
// `if (entry.type !== 'autogenerated') continue;`, so it skips this sidebar
// entirely. tests/docs-contract.test.mjs derives its directory list from the
// autogenerated entries too, so docs/architectures/ is outside its reach as
// well. Nothing else in the suite reads sidebars.js for anything but the
// navbar wiring in tests/site-config.test.mjs.
//
// The result is that `REPO_AUTHORED_PAGES` in scripts/lib/architecture-pages.mjs
// and the id list in sidebars.js restate the same set by hand, in two files,
// with nothing holding them together. Both drift directions build green:
//
//   - A third repo-authored page added to docs/architectures/ and to
//     REPO_AUTHORED_PAGES, but not to the sidebar, is published and exempted
//     from the imported-content gate while being reachable from no menu.
//   - An imported page added to the sidebar renders with the sidebar rail
//     instead of full-width, which is the layout the comment says the
//     omission is there to produce. Docusaurus resolves the id, so the build
//     says nothing.
//
// Only the third direction -- an id that resolves to no page -- is caught
// today, and then only by `docusaurus build`, not by the unit suite.
import assert from 'node:assert/strict';
import { existsSync } from 'node:fs';
import { join } from 'node:path';
import test from 'node:test';
import { fileURLToPath } from 'node:url';

import {
  REPO_AUTHORED_PAGES,
  listArchitecturePages,
} from '../scripts/lib/architecture-pages.mjs';

const repoRoot = fileURLToPath(new URL('..', import.meta.url));
const docsRoot = join(repoRoot, 'docs');
const architecturesDir = join(docsRoot, 'architectures');

const sidebars = (await import('../sidebars.js')).default;

const SIDEBAR_ID = 'architecturesSidebar';
const DOCS_DIR = 'architectures';

// Page extensions @docusaurus/plugin-content-docs globs by default, matching
// PAGE_EXTENSION in scripts/lib/architecture-pages.mjs. A doc id carries no
// extension, so resolving one back to disk has to try both.
const PAGE_EXTENSIONS = ['.md', '.mdx'];

/**
 * Every doc id a sidebar definition names, walking the shapes Docusaurus
 * accepts. `{type: 'autogenerated'}` contributes no explicit id -- its
 * contents come from the filesystem -- and is reported separately so the
 * caller can tell "names no id" apart from "names ids elsewhere".
 */
function explicitDocIds(entries) {
  const ids = [];
  const walk = (list) => {
    for (const entry of list ?? []) {
      if (typeof entry === 'string') {
        ids.push(entry);
        continue;
      }
      if (entry?.type === 'doc' && typeof entry.id === 'string') {
        ids.push(entry.id);
        continue;
      }
      if (entry?.type === 'category') {
        if (entry.link?.type === 'doc' && typeof entry.link.id === 'string') {
          ids.push(entry.link.id);
        }
        walk(entry.items);
      }
    }
  };
  walk(entries);
  return ids;
}

/** Whether a sidebar definition contains an autogenerated entry. */
function hasAutogenerated(entries) {
  return (entries ?? []).some((entry) => entry?.type === 'autogenerated');
}

/** The doc id a docs/architectures-relative page path is published under. */
function docIdForPage(relativePath) {
  const extension = PAGE_EXTENSIONS.find((suffix) =>
    relativePath.endsWith(suffix),
  );
  const stem = extension
    ? relativePath.slice(0, -extension.length)
    : relativePath;
  return `${DOCS_DIR}/${stem}`;
}

/** Whether a doc id resolves to a published page on disk. */
function docIdExists(id) {
  return PAGE_EXTENSIONS.some((extension) =>
    existsSync(join(docsRoot, `${id}${extension}`)),
  );
}

const { pages } = listArchitecturePages(architecturesDir);
const repoAuthoredIds = [...REPO_AUTHORED_PAGES].map(docIdForPage).sort();
const importedIds = pages
  .filter((page) => !REPO_AUTHORED_PAGES.has(page))
  .map(docIdForPage)
  .sort();

test(`sidebars.js defines ${SIDEBAR_ID} as a hand-listed sidebar`, () => {
  const entries = sidebars[SIDEBAR_ID];
  assert.ok(
    Array.isArray(entries),
    `sidebars.js must define ${SIDEBAR_ID} as a list`,
  );
  assert.ok(entries.length > 0, `${SIDEBAR_ID} must not be empty`);
  assert.equal(
    hasAutogenerated(entries),
    false,
    `${SIDEBAR_ID} must stay hand-listed: an autogenerated entry over ` +
      `docs/${DOCS_DIR} would pull every imported page into the menu`,
  );
});

test('the repo-authored page set is non-empty, so the contracts below are not vacuous', () => {
  assert.ok(
    repoAuthoredIds.length > 0,
    'REPO_AUTHORED_PAGES in scripts/lib/architecture-pages.mjs is empty',
  );
});

test(`every ${SIDEBAR_ID} entry resolves to a page on disk`, () => {
  const missing = explicitDocIds(sidebars[SIDEBAR_ID]).filter(
    (id) => !docIdExists(id),
  );
  assert.deepEqual(
    missing,
    [],
    `${SIDEBAR_ID} names doc ids that match no .md or .mdx under docs/`,
  );
});

test(`${SIDEBAR_ID} lists exactly the repo-authored architecture pages`, () => {
  assert.deepEqual(
    explicitDocIds(sidebars[SIDEBAR_ID]).sort(),
    repoAuthoredIds,
    `${SIDEBAR_ID} in sidebars.js and REPO_AUTHORED_PAGES in ` +
      'scripts/lib/architecture-pages.mjs restate the same set by hand. A ' +
      'repo-authored page missing here is published but reachable from no ' +
      'menu; an extra id here is a page the imported-content gate exempts ' +
      'without this sidebar meaning to carry it.',
  );
});

test('docs/architectures holds imported pages, so the exclusion below is not vacuous', () => {
  assert.ok(
    importedIds.length > 0,
    'no imported architecture pages on disk: the exclusion contract would ' +
      'pass against an empty set',
  );
});

test('no imported architecture page appears in any sidebar', () => {
  const imported = new Set(importedIds);
  const leaked = [];
  for (const [id, entries] of Object.entries(sidebars)) {
    for (const docId of explicitDocIds(entries)) {
      if (imported.has(docId)) leaked.push(`${id}: ${docId}`);
    }
  }
  assert.deepEqual(
    leaked,
    [],
    'imported architecture pages are left out of every sidebar so they render ' +
      'full-width (sidebars.js); listing one gives it the sidebar rail with a ' +
      'green build',
  );
});

// The helpers above decide every assertion in this file, and against the tree
// on disk each one returns the empty/clean answer. Driving their other arms
// from fixtures is what keeps a green run here evidence that the contracts
// were checked rather than evidence that nothing was there to find -- the
// convention tests/ci-supply-chain.test.mjs states for its own scanners.

test('explicitDocIds reads the entry shapes Docusaurus accepts', () => {
  assert.deepEqual(
    explicitDocIds([
      'plain/string',
      { type: 'doc', id: 'object/form' },
      { type: 'autogenerated', dirName: 'community' },
      {
        type: 'category',
        label: 'Nested',
        link: { type: 'doc', id: 'category/landing' },
        items: ['category/child', { type: 'doc', id: 'category/grandchild' }],
      },
      { type: 'link', label: 'External', href: 'https://example.com' },
      { type: 'doc' },
      {
        type: 'category',
        label: 'Generated',
        link: { type: 'generated-index' },
      },
    ]),
    [
      'plain/string',
      'object/form',
      'category/landing',
      'category/child',
      'category/grandchild',
    ],
  );
});

test('explicitDocIds tolerates an absent or empty entry list', () => {
  assert.deepEqual(explicitDocIds(undefined), []);
  assert.deepEqual(explicitDocIds([]), []);
  assert.deepEqual(explicitDocIds([null]), []);
});

test('hasAutogenerated distinguishes the two sidebar styles', () => {
  assert.equal(hasAutogenerated(['architectures/index']), false);
  assert.equal(hasAutogenerated(undefined), false);
  assert.equal(
    hasAutogenerated([{ type: 'autogenerated', dirName: 'architectures' }]),
    true,
  );
});

test('docIdForPage strips both published extensions and nothing else', () => {
  assert.equal(docIdForPage('index.md'), `${DOCS_DIR}/index`);
  assert.equal(docIdForPage('submit.mdx'), `${DOCS_DIR}/submit`);
  assert.equal(docIdForPage('nested/page.md'), `${DOCS_DIR}/nested/page`);
  assert.equal(docIdForPage('no-extension'), `${DOCS_DIR}/no-extension`);
});

test('docIdExists answers against the docs tree on disk', () => {
  assert.equal(docIdExists(`${DOCS_DIR}/index`), true);
  assert.equal(docIdExists(`${DOCS_DIR}/this-page-does-not-exist`), false);
});
